"""Beginner explanations for compiler getters and assembly annotations."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1765': ('남의 책상을 잠깐 사용했다면 끝난 뒤 원래 상태로 돌려놓아야 해요. 검사 정보를 찾는 도우미도 호출한 쪽의 접근 상태를 기억했다가 되돌려요.', '저장·조회·복구의 순서와 반환값의 차이를 이해합니다.', 'save → 검사 정보 조회 → restore → 결과 반환을 쓰고, save의 결과에서 restore의 인자로 화살표를 그리세요.', ['get_shadow_origin_ptr는 데이터 주소에 대응하는 검사 정보 주소를 얻는 공통 도우미예요. shadow는 값의 준비 상태표이고 origin은 원인 정보표예요. 포인터는 이 표가 있는 곳을 가리키는 주소예요.', '먼저 user_access_save를 호출해 결과를 ua_flags에 저장해요. uaccess는 커널이 사용자 메모리에 접근할 때의 상태와 관련된 말이에요. 이 함수가 저장하는 상태의 구체적인 비트와 처리 방식은 기종에 따라 달라질 수 있어요.', '그다음 kmsan_get_shadow_origin_ptr에 addr, size, store를 전달해요. addr는 데이터 시작 주소, size는 바이트 수, store는 쓰기 작업인지 나타내요. 조회 결과인 두 검사 정보 포인터는 ret에 보관해요.', '조회가 정상적으로 돌아오면 user_access_restore(ua_flags)를 호출해 앞에서 저장한 상태를 복구해요. 언제나 0을 넣는 것이 아니라 같은 호출에서 save가 돌려준 값을 사용해요. 마지막에는 ret를 반환해요.', 'ua_flags와 ret는 역할이 달라요. ua_flags는 호출 전 상태를 되돌리는 데 쓰고 ret는 찾은 검사 정보 주소를 돌려주는 데 써요. 예시 상태 번호가 37이었다면 복구에 37을 전달한다고 생각할 수 있지만, 37은 실제 기종의 고정 설정값이 아니에요.', '이 짧은 함수에는 KMSAN 활성 여부나 kmsan_in_runtime을 검사해 조회를 생략하는 조건문이 없어요. 아래에서 부르는 실제 조회 함수의 정책과 이 도우미의 역할을 구별하세요. 다른 함수에 있던 조기 반환 조건을 여기에도 있다고 추측하지 마세요.'], [('restore에 전달하는 ua_flags는 어디에서 얻나요?', ['호출할 때마다 무조건 숫자 0을 만들어요', '앞에서 실행한 user_access_save의 반환값을 보관해요'], '정답은 두 번째예요. save의 결과를 지역 변수 ua_flags에 넣었다가 restore에 전달해요. 검사 정보 주소를 담은 ret와는 다른 값이에요.'), ('이 도우미 자체에 runtime 안이면 조회를 건너뛰는 조건문이 있나요?', ['아니요. 본문은 저장·조회·복구·반환 순서예요', '네. 맨 앞에서 모든 runtime 조회를 금지해요'], '정답은 첫 번째예요. 본문에 그런 if문이 없어요. 실제로 부르는 조회 함수가 어떤 결과를 주는지는 별도로 살펴야 해요.')]), 'os1766': ('도서관에서 책 내용을 읽어 주는 일과 그 책이 있는 서가 위치를 알려 주는 일은 달라요. 이 함수들은 검사표가 있는 위치를 알려 줘요.', '가변 길이 조회의 주소·길이·방향 인자를 구별합니다.', '11바이트 읽기는 (주소, 11, false), 13바이트 쓰기는 (주소, 13, true)로 적어 보세요.', ['load는 메모리에서 읽기, store는 메모리에 쓰기를 뜻해요. 하지만 여기의 __msan_metadata_ptr_for_load_n과 store_n은 실제 데이터 연산을 대신하는 함수가 아니에요. 그 연산에 필요한 검사 정보 주소를 찾는 도우미예요.', '이름 끝의 n은 길이를 별도 인자로 받는 형태예요. 1·2·4·8바이트처럼 함수 이름에 고정 길이를 붙인 형태와 구별해요. 본문은 전달받은 size를 그대로 사용하며 특정 숫자인지 따로 검사하지 않아요.', 'load_n은 공통 도우미에 addr, size, false를 전달해요. 마지막 false는 쓰기가 아니라 읽기라는 표시예요. 예를 들어 11바이트 읽기 요청이면 길이 11을 그대로 전달해요.', 'store_n은 같은 공통 도우미에 addr, size, true를 전달해요. true는 쓰기라는 표시예요. 13바이트 쓰기 요청이면 길이 13과 true가 전달돼요. 방향이 다르다고 이 함수가 길이를 자동으로 바꾸지는 않아요.', '반환형 shadow_origin_ptr는 두 포인터를 묶은 구조체예요. 구조체는 관련 값을 한 상자에 담는 C의 자료형이에요. 여기서는 준비 상태표 shadow와 원인 정보표 origin의 주소를 함께 돌려줘요.', '컴파일러는 프로그램을 기계가 실행할 형태로 바꾸면서 검사 코드를 덧붙일 수 있어요. 이 함수는 그 검사 코드가 부르는 통로예요. load라는 이름만 보고 데이터에서 읽은 정수 값을 반환한다고 생각하면 반환형의 뜻을 놓치게 돼요.'], [('load_n이 반환하는 상자에는 무엇이 들어 있나요?', ['실제 데이터에서 읽은 정수 값 하나예요', 'shadow와 origin 검사 정보의 포인터예요'], '정답은 두 번째예요. 반환형은 shadow_origin_ptr예요. 원래 데이터 내용과 검사 정보를 찾아갈 주소를 구별하세요.'), ('store_n이 마지막 인자로 전달하는 store 값은 무엇인가요?', ['쓰기를 뜻하는 true예요', '읽기를 뜻하는 false예요'], '정답은 첫 번째예요. store_n은 true, load_n은 false를 전달해요. 주소와 길이는 각각 받은 값을 그대로 넘겨요.')]), 'os1767': ('같은 모양의 이름표를 크기별로 여러 번 만들 때 빈칸이 있는 틀을 쓸 수 있어요. C의 매크로도 정해진 틀에 숫자를 넣어 비슷한 코드를 만들어요.', '매크로 확장과 함수 실행을 구별하고 생성된 함수 수를 계산합니다.', '크기 1, 2, 4, 8 네 줄에 load와 store 두 칸씩 그려 총 여덟 칸인지 세어 보세요.', ['DECLARE_METADATA_PTR_GETTER(size)는 비슷한 함수 코드를 만드는 매크로예요. 매크로는 전처리 단계에서 펼쳐지는 코드 틀이에요. 프로그램 실행 중에 크기를 알아맞혀 새 함수를 만드는 방식이 아니에요.', '##는 두 토큰을 붙이는 전처리 기호예요. 토큰은 코드에서 이름이나 숫자처럼 하나로 다루는 조각이에요. load_##size에 4를 넣으면 load_4처럼 숫자가 붙은 이름 조각이 만들어져요.', '크기 4를 넣으면 __msan_metadata_ptr_for_load_4와 __msan_metadata_ptr_for_store_4라는 함수가 생겨요. 읽기 함수는 공통 도우미에 주소, 4, false를 전달하고 쓰기 함수는 주소, 4, true를 전달해요.', '원문은 이 틀에 1, 2, 4, 8을 각각 넣어요. 크기마다 읽기와 쓰기 두 함수이므로 4 × 2 = 8개예요. 앞 수업의 가변 길이 함수 두 개는 이 여덟 개를 셀 때 포함하지 않아요.', '각 함수 앞에는 함수 이름과 인자 모양을 알려 주는 선언도 있어요. 선언과 실제 본문이 두 번 보인다고 서로 다른 함수 두 개로 세지 마세요. 원문 주석은 앞의 선언으로 missing-prototypes 경고를 막는다고 설명해요.', 'EXPORT_SYMBOL은 해당 이름을 커널 모듈에서 참조할 수 있도록 내보내는 표시예요. 매크로는 선언·본문·내보내기 표시를 함께 만들어요. 줄 끝의 역슬래시는 긴 매크로 정의가 다음 줄까지 이어진다는 뜻이에요.'], [('크기 1, 2, 4, 8에서 읽기·쓰기 함수를 하나씩 만들면 총 몇 개인가요?', ['크기가 네 개이므로 함수도 네 개예요', '각 크기마다 두 개씩이므로 여덟 개예요'], '정답은 두 번째예요. 4 × 2 = 8이에요. 같은 함수의 선언과 본문은 따로 세지 않아요.'), ('##size로 함수 이름에 숫자를 붙이는 때는 언제인가요?', ['실행 전에 코드를 펼치는 전처리 단계예요', '메모리를 읽을 때마다 실행 중에 이름 문자열을 만들어요'], '정답은 첫 번째예요. ##는 전처리 토큰 결합이에요. 실행되는 함수가 문자열을 이어 붙이는 동작과는 달라요.')]), 'os1768': ('실제로 숙제를 끝냈는데 검사표에 표시가 빠지면 안 했다는 지적을 받을 수 있어요. 반대로 확인 없이 끝났다고 표시하면 진짜 미완성도 놓칠 수 있어요.', '어셈블리 출력의 검사 표시를 바꾸는 이유와 한계를 이해합니다.', '실제 기록 있음·검사 표시 없음의 잘못된 경고와 실제 기록 없음·준비됨 표시의 누락을 두 줄로 비교하세요.', ['인라인 어셈블리는 C 코드 안에 CPU 명령을 직접 적는 방법이에요. 컴파일러의 검사 코드가 그 안에서 실제로 일어난 모든 쓰기를 제대로 추적하지 못할 수 있어요. 그러면 이미 값을 썼는데도 미준비 상태로 잘못 판단할 수 있어요.', '__msan_instrument_asm_store는 이런 출력 범위를 unpoison해요. unpoison은 검사표를 준비됨으로 바꾼다는 뜻이에요. 실제 데이터에 새 값을 쓰거나 0을 채우는 동작은 아니에요.', '이 함수는 kmsan_internal_unpoison_memory에 addr, size, false를 전달해요. 마지막 false는 checked 옵션을 끈다는 표시예요. 주소 분류 같은 앞의 조건도 있으므로 false 하나만 보고 모든 검사를 아무 조건 없이 생략한다고 읽지는 마세요.', '검사 도구가 꺼져 있으면 먼저 끝나요. 켜져 있으면 사용자 접근 상태를 저장하고 길이와 주소를 살핀 뒤 표시를 바꾸고 상태를 복구해요. 주소 분류에서 제외되면 그 경로에서도 상태를 복구한 뒤 돌아가요.', '길이가 4096보다 크면 경고하고, 경고 뒤 실행이 계속되는 경우 길이를 8로 바꿔 처리해요. 4096으로 줄이는 코드가 아니에요. 이 세부 정책 때문에 모든 요청 바이트를 항상 준비됨으로 표시한다고 단정할 수 없어요.', '고정 원문의 공식 설명은 이 방식이 잘못된 경고를 줄이는 대신 실제 오류 일부를 가릴 수도 있다고 말해요. 실제로 안 쓴 곳까지 준비됨으로 표시하면 미초기화 읽기를 놓칠 수 있기 때문이에요. 이 표시를 받았다는 사실만으로 모든 어셈블리 코드가 안전하다고 증명되지는 않아요.'], [('실제 unpoison 호출에 전달하는 checked 값은 무엇인가요?', ['항상 true예요', 'false예요'], '정답은 두 번째예요. 원문 인자에 checked false가 있어요. 앞에서 길이와 주소를 처리하는 코드가 있다는 점과 구별해 읽으세요.'), ('어셈블리 출력을 준비됨으로 표시하는 방식이 실제 오류를 놓치게 할 수도 있나요?', ['네. 실제로 준비되지 않은 부분까지 표시하면 놓칠 수 있어요', '아니요. 표시 하나로 모든 명령의 안전성이 증명돼요'], '정답은 첫 번째예요. 공식 설명은 일부 오류를 가릴 수 있다고 밝히고 있어요. 잘못된 경고를 줄이는 효과와 오류를 놓칠 가능성을 함께 이해해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_437.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
